/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean rsr_feature_enabled( Rsr_Feature_Index index )
{
	if ( index >= RS_FEAT_COUNT )
	{
		rsr_feature_err_add ( RS_FEAT_ERR_INVALID_INDEX );
		return FALSE;
	}
	return rsr_feature_list[index].enabled;
}

